function number(value, fallback = 0) {
  if (value === null || value === undefined || value === '') return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function bool(value) {
  return value === true || String(value).toLowerCase() === 'true';
}

function round(value, digits = 2) {
  const scale = 10 ** digits;
  return Math.round((number(value) + Number.EPSILON) * scale) / scale;
}

function pct(curr, prev) {
  if (number(prev) === 0) return null;
  return round(((number(curr) - number(prev)) / number(prev)) * 100, 1);
}

function metric(current, previous, change, directionValue, unit) {
  let display;
  if (change === null || change === undefined) {
    if (number(previous) === 0 && number(current) > 0) display = '↑mới';
    else if (number(previous) > 0 && number(current) === 0) display = '↓100%';
    else display = '→0%';
  } else {
    const arrow = directionValue === 'up' ? '↑' : (directionValue === 'down' ? '↓' : '→');
    display = arrow + Math.abs(number(change)) + (unit === 'pp' ? ' điểm %' : '%');
  }
  const result = {
    current: number(current),
    previous: number(previous),
    direction: directionValue,
    display,
  };
  if (unit === 'pp') result.change_pp = change === null || change === undefined ? null : number(change);
  else result.change_pct = change === null || change === undefined ? null : number(change);
  return result;
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function direction(curr, baseline, history90, minVolume, thresholdPct) {
  const current = number(curr);
  const base = number(baseline);
  const lowVolume = (current * 7) < minVolume && number(history90) < minVolume;
  if (lowVolume) return 'flat';
  if (base === 0 && current === 0) return 'flat';
  if (base === 0 && current > 0) return 'up';
  if (current === 0 && base > 0) return 'down';
  const change = ((current - base) / base) * 100;
  if (change >= thresholdPct) return 'up';
  if (change <= -thresholdPct) return 'down';
  return 'flat';
}

function overallDirection(curr, prev, minVolume, thresholdPct) {
  const current = number(curr);
  const base = number(prev);
  if (current < minVolume && base < minVolume) return 'flat';
  if (base === 0 && current >= minVolume) return 'up';
  if (current === 0 && base >= minVolume) return 'down';
  return direction(current, base, Math.max(current, base), 0, thresholdPct);
}

function statusRank(status) {
  return { red: 4, orange: 3, yellow: 2, normal: 1 }[status] || 0;
}

function courseTrend(row, cfg, reportDate) {
  const minVolume = number(cfg.thresholds.min_base_volume);
  const trendPct = number(cfg.thresholds.trend_direction_pct);
  const lead = {
    curr7: number(row.lead_n_curr7), prev7: number(row.lead_n_prev7),
    prev30: number(row.lead_n_prev30), prev90: number(row.lead_n_prev90),
  };
  const won = {
    curr7: number(row.won_n_curr7), prev7: number(row.won_n_prev7),
    prev30: number(row.won_n_prev30), prev90: number(row.won_n_prev90),
  };
  const leadDirections = {
    prev7: direction(lead.curr7 / 7, lead.prev7 / 7, lead.prev90, minVolume, trendPct),
    prev30: direction(lead.curr7 / 7, lead.prev30 / 30, lead.prev90, minVolume, trendPct),
    prev90: direction(lead.curr7 / 7, lead.prev90 / 90, lead.prev90, minVolume, trendPct),
  };
  const wonDirections = {
    prev7: direction(won.curr7 / 7, won.prev7 / 7, won.prev90, minVolume, trendPct),
    prev30: direction(won.curr7 / 7, won.prev30 / 30, won.prev90, minVolume, trendPct),
    prev90: direction(won.curr7 / 7, won.prev90 / 90, won.prev90, minVolume, trendPct),
  };
  const leadDownCount = Object.values(leadDirections).filter((value) => value === 'down').length;
  const wonDownCount = Object.values(wonDirections).filter((value) => value === 'down').length;
  const hasEverLead = bool(row.has_ever_had_lead);
  const daysNoLead = row.days_no_lead === null || row.days_no_lead === undefined ? null : number(row.days_no_lead);
  const lowVolume = lead.curr7 < minVolume && lead.prev90 < minVolume;
  const lowWonVolume = won.curr7 < minVolume && won.prev90 < minVolume;
  const flagNoLead = hasEverLead && daysNoLead !== null
    && daysNoLead >= number(cfg.thresholds.warning_zero_lead_days)
    && lead.prev90 >= minVolume;

  let status = 'normal';
  if (!lowVolume && leadDirections.prev7 === 'down' && wonDirections.prev7 === 'down'
      && (leadDirections.prev30 === 'down' || leadDirections.prev90 === 'down'
          || wonDirections.prev30 === 'down' || wonDirections.prev90 === 'down')) status = 'red';
  else if (flagNoLead || leadDownCount >= 2 || wonDownCount >= 2
      || (leadDirections.prev7 === 'down' && wonDirections.prev7 === 'down')) status = 'orange';
  else if (leadDownCount + wonDownCount > 0) status = 'yellow';

  let interpretationCode = 'STABLE_OR_UP';
  if (flagNoLead) interpretationCode = 'NO_LEAD';
  else if (lowVolume) interpretationCode = 'LOW_VOLUME';
  else if (leadDirections.prev7 === 'down' && wonDirections.prev7 === 'down') interpretationCode = 'LEAD_AND_WON_DOWN';
  else if (leadDirections.prev7 === 'down' && wonDirections.prev7 !== 'down') interpretationCode = 'LEAD_DOWN_WON_OK';
  else if (leadDirections.prev7 !== 'down' && wonDirections.prev7 === 'down') interpretationCode = 'WON_DOWN_LEAD_OK';
  else if ([...Object.values(leadDirections), ...Object.values(wonDirections)].includes('down')) interpretationCode = 'MIXED_TREND';

  const reasons = [];
  if (leadDownCount) reasons.push('LEAD_DOWN_' + leadDownCount + '_BASELINES');
  if (wonDownCount) reasons.push('WON_DOWN_' + wonDownCount + '_BASELINES');
  if (flagNoLead) reasons.push('NO_LEAD_' + daysNoLead + '_DAYS');

  return {
    course_key: row.course_key,
    course_name: row.course_name,
    course_type: row.course_type,
    lead_n_curr7: lead.curr7, lead_n_prev7: lead.prev7, lead_n_prev30: lead.prev30, lead_n_prev90: lead.prev90,
    lead_pd_curr7: round(lead.curr7 / 7), lead_pd_prev7: round(lead.prev7 / 7),
    lead_pd_prev30: round(lead.prev30 / 30), lead_pd_prev90: round(lead.prev90 / 90),
    lead_vs_prev7: leadDirections.prev7, lead_vs_prev30: leadDirections.prev30, lead_vs_prev90: leadDirections.prev90,
    won_n_curr7: won.curr7, won_n_prev7: won.prev7, won_n_prev30: won.prev30, won_n_prev90: won.prev90,
    won_pd_curr7: round(won.curr7 / 7), won_pd_prev7: round(won.prev7 / 7),
    won_pd_prev30: round(won.prev30 / 30), won_pd_prev90: round(won.prev90 / 90),
    won_vs_prev7: wonDirections.prev7, won_vs_prev30: wonDirections.prev30, won_vs_prev90: wonDirections.prev90,
    last_lead_date: row.last_lead_date || null,
    days_no_lead: daysNoLead,
    has_ever_had_lead: hasEverLead,
    baseline_lead_expected7: round((lead.prev90 / 90) * 7, 1),
    baseline_lead_expected5: round((lead.prev90 / 90) * 5, 1),
    is_low_volume: lowVolume,
    is_low_won_volume: lowWonVolume,
    flag_no_lead: flagNoLead,
    lead_down_count: leadDownCount,
    won_down_count: wonDownCount,
    status,
    status_reason: reasons,
    interpretation_code: interpretationCode,
    lead_change_prev7_pct: pct(lead.curr7, lead.prev7),
    won_change_prev7_pct: pct(won.curr7, won.prev7),
  };
}

