const unmappedCount = q6.filter((row) => row.mapping_status === 'UNMAPPED_COURSE').reduce((sum, row) => sum + number(row.issue_count), 0);
const issueCount = missingCount + unmappedCount;
const issueRate = totalLeads ? round(issueCount / totalLeads * 100, 1) : 0;
const dataSevere = issueCount >= number(cfg.thresholds.unmapped_alert_min)
  && issueRate >= number(cfg.thresholds.unmapped_alert_rate_pct);

const priorityItems = [];
const broadWarnings = warnings.filter((course) => course.lead_down_count > 0 && course.won_down_count > 0);
if (broadWarnings.length) priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'COURSE_TREND_DOWN', course_names: broadWarnings.map((c) => c.course_name) });
if (newNoLeadWeekly.length) priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'NEW_NO_LEAD_WEEKLY', course_names: newNoLeadWeekly.map((c) => c.course_name) });
if (noLeadHistory.length) priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'NO_LEAD_HISTORY', course_names: noLeadHistory.map((c) => c.course_name) });
if (bool(cfg.features.enable_weekly_stale_open) && warnings.some((course) => course.stale_open_flag)) {
  priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'WEEKLY_STALE_OPEN', course_names: warnings.filter((c) => c.stale_open_flag).map((c) => c.course_name) });
}

const continueCourses = unique([
  ...courseGroups.good.map((course) => course.course_name),
  ...courseGroups.watch.filter((course) => course.role_codes.includes('MOST_IMPROVED')
    && course.lead_week_direction === 'up').map((course) => course.course_name),
]);
const continueContent = unique([
  ...topByLeads.slice(0, 1).map((row) => row.utm_content),
  ...topByWon.slice(0, 1).map((row) => row.utm_content),
]);
const priorityCourses = courseGroups.action_now
  .filter((course) => ['BROAD_LEAD_WON_DECLINE', 'RECENT_ZERO_BROAD_LEAD_WON_DECLINE'].includes(course.interpretation_code)
    || (course.lead_7d_direction === 'down' && course.won_7d_direction === 'down'))
  .map((course) => course.course_name);
const restoreCourses = newNoLeadWeekly.map((course) => course.course_name);

const writerPayload = {
  schema_version: cfg.schema_version,
  report_mode: 'weekly',
  week: { label: rd.week_label, previous_label: rd.previous_week_label },
  overall: {
    acquisition: {
      lead: metric(q3.leads_curr, q3.leads_prev, q3.leads_pct_change, overall.lead_direction, 'pct'),
      mql: metric(q3.mql_curr, q3.mql_prev, q3.mql_pct_change, overall.mql_direction, 'pct'),
    },
    sales_funnel: {
      discovery: metric(q3.discovery_curr, q3.discovery_prev, q3.discovery_pct_change, overall.discovery_direction, 'pct'),
      need_fit: metric(q3.needfit_curr, q3.needfit_prev, q3.needfit_pct_change, overall.needfit_direction, 'pct'),
    },
    outcome: {
      won: metric(q3.won_curr, q3.won_prev, q3.won_pct_change, overall.won_direction, 'pct'),
      lost: metric(q3.lost_curr, q3.lost_prev, q3.lost_pct_change, overall.lost_direction, 'pct'),
      cvr: metric(q3.cvr_curr, q3.cvr_prev, q3.cvr_change_pp, overall.cvr_direction, 'pp'),
    },
    summary_code: overall.summary_code,
  },
  course_performance: courseGroups,
  lead_sources: {
    top_by_leads: topByLeads.map((row) => compactContent(row)),
    top_by_won: topByWon.map((row) => compactContent(row, true)),
    tracking: {
      untracked_leads: untrackedLeads,
      untracked_share_pct: totalLeads ? round(untrackedLeads / totalLeads * 100, 1) : 0,
    },
    insight_code: untrackedLeads > 0 && totalLeads && (untrackedLeads / totalLeads) >= 0.3
      ? 'TOP_SIGNALS_WITH_HIGH_UNTRACKED' : 'TOP_SIGNALS',
  },
  no_lead: {
    recent_zero: newNoLeadWeekly.map((course) => ({
      course_name: course.course_name,
      days_no_lead: course.days_no_lead,
    })),
    history_total: noLeadHistory.length,
    history: noLeadHistory.map((course) => ({
      course_name: course.course_name,
      days_no_lead: course.days_no_lead,
    })),
  },
  next_week: {
    continue: {
      course_names: continueCourses,
      content_names: continueContent,
      reason_code: 'KEEP_POSITIVE_SIGNAL',
    },
    priority: {
      course_names: priorityCourses,
      reason_code: 'BROAD_LEAD_WON_DECLINE',
    },
    restore_acquisition: {
      course_names: restoreCourses,
      reason_code: 'RECENT_ZERO_LEAD',
    },
    goal_code: 'KEEP_RECOVER_STOP_DECLINE',
  },
  writer_rules: {
    no_root_cause: true,
    no_revenue: true,
    no_recalculation: true,
    omit_empty_subgroups: true,
  },
};

return [{ json: {
  schema_version: cfg.schema_version,
  report_mode: 'weekly',
  run_id: rd.run_id,
  run_date: rd.run_date,
  report_date: rd.report_date,
  report_date_display: rd.report_date_display,
  week_label: rd.week_label,
  previous_week_label: rd.previous_week_label,
  periods: rd.periods,
  overall,
  course_leaderboard: {
    strongest: { eligible: Boolean(strongest), course: strongest, reason_codes: strongest ? ['WON_DESC', 'CVR_SAMPLE_GATED'] : [] },
    most_improved: { eligible: Boolean(improved), course: improved, reason_codes: improved ? ['LEAD_CHANGE_DESC'] : [] },
    most_declined: { eligible: Boolean(declined), course: declined, reason_codes: declined ? ['LEAD_CHANGE_ASC'] : [] },
    weakest: { eligible: Boolean(weakest), course: weakest, reason_codes: weakest ? ['WON_ASC', 'CVR_SAMPLE_GATED'] : [] },
  },
  content_performance: {
    top_by_leads: topByLeads,
    top_by_won: topByWon,
    top_by_cvr: topByCvr,
    untracked: { n_leads: untrackedLeads, share_pct: totalLeads ? round(untrackedLeads / totalLeads * 100, 1) : 0 },
    cvr_label: 'CVR cohort hiện tại',
  },
  warnings: { total: warnings.length, courses: warnings, display_courses: warnings },
  no_lead_history: { threshold_days: historyThreshold, total: noLeadHistory.length, courses: noLeadHistory, display_courses: noLeadHistory },
  new_no_lead_weekly: { total: newNoLeadWeekly.length, courses: newNoLeadWeekly },
  priority_items: priorityItems.slice(0, number(cfg.limits.weekly_priority_limit)),
  data_health: {
    total_leads: totalLeads,
    missing_course_count: missingCount,
    unmapped_course_count: unmappedCount,
    unmapped_rate_pct: issueRate,
    untracked_utm_count: untrackedLeads,
    is_severe: dataSevere,
    alert_text_code: dataSevere ? 'COURSE_MAPPING_ISSUE' : null,
    rows: q6,
  },
  writer_rules: {
    priority_limit: number(cfg.limits.weekly_priority_limit),
    show_data_health_alert: bool(cfg.features.show_weekly_data_health_alert) && dataSevere,
    show_weekly_stale_open: bool(cfg.features.enable_weekly_stale_open),
  },
  writer_payload: writerPayload,
} }];

const payload = $('Build Daily Payload').first().json;
const text = String($json.output || $json.text || '').trim();
return [{ json: {
  run_id: payload.run_id,
  report_date: payload.report_date,
  sent_at: new Date().toISOString(),
  query_results: JSON.stringify(payload),
  agent_output: text,
  status: 'success',
  error_message: null,
} }];

const payload = $('Build Weekly Payload').first().json;
const text = String($json.output || $json.text || '').trim();
return [{ json: {
  run_id: payload.run_id,
  report_date: payload.report_date,
  sent_at: new Date().toISOString(),
  query_results: JSON.stringify(payload),
  agent_output: text,
  status: 'success',
  error_message: null,
} }];

return [{ json: {
  run_id: $json.run_id,
  report_date: $json.report_date,
  sent_at: $json.sent_at,
  query_results: $json.query_results,
  agent_output: $json.agent_output,
  status: $json.status,
  error_message: $json.error_message,
} }];
